interface User {
  id: number;
  name: string;
  email: string;
  age?: number;        // Optional property
  readonly createdAt: Date; // Read-only property
}

function getUser(id: number): User {
  return {
    id,
    name: 'Alice',
    email: 'alice@example.com',
    createdAt: new Date()
  };
}

type User = {
  id: number;
  name: string;
  email: string;
};

// Union types (only possible with type)
type Status = 'idle' | 'loading' | 'success' | 'error';

// Intersection types
type Employee = User & {
  role: string;
  department: string;
};
